input.command:
cd /tmp && echo "=== Sections (fixed regex) ==="; for t in "Register" "Sign up\|Sign Up" "Reels" "Privacy" "Terms" "Invest" "Contact" "og:image" "og:title" "og:description" "twitter:card" "viewport" "description"; do printf "%-20s " "$t:"; rg -io "$t" l1.html | head -1; echo; done; echo "=== API base in page ==="; rg -o 'https://[a-z0-9.-]*onrender[a-z0-9.-]*' l1.html | sort -u | head -3; rg -o '/api/[a-z0-9/_-]+' l1.html | sort -u | head -10; echo "=== robots/sitemap ==="; curl -s -m 15 -o /dev/null -w "robots.txt: %{http_code}
" https://ivxholding.com/robots.txt; curl -s -m 15 -o /dev/null -w "sitemap.xml: %{http_code}
" https://ivxholding.com/sitemap.xml; echo "=== favicon ==="; curl -s -m 15 -o /dev/null -w "favicon: %{http_code} (%{content_type})
" https://ivxholding.com/favicon.ico

B=https://ivx-holdings-platform.onrender.com; echo "=== Invalid login (expect 401, no enumeration) ==="; curl -s -m 30 -o login.json -w "HTTP %{http_code}
" -X POST "$B/api/members/login" -H "Content-Type: application/json" -d '{"email":"nobody-xyz@invalid.test","password":"WrongPass123!"}'; head -c 200 login.json; echo; echo "=== Invalid registration (expect 400 validation) ==="; curl -s -m 30 -o reg.json -w "HTTP %{http_code}
" -X POST "$B/api/members/register" -H "Content-Type: application/json" -d '{"email":"bad","password":"x","fullName":""}'; head -c 250 reg.json; echo; echo "=== Reel asset playable (from feed) ==="; V=$(rg -o '"video_url":"[^"]+"' /tmp/feed.json | head -1 | sed 's/"video_url":"//;s/"$//'); P=$(rg -o '"poster_url":"[^"]+"' /tmp/feed.json | head -1 | sed 's/"poster_url":"//;s/"$//'); echo "video: $V"; curl -s -m 20 -o /dev/null -w "video HEAD: %{http_code} | %{content_type} | %{size_download}B
" -I "$V"; curl -s -m 20 -o /dev/null -w "poster HEAD: %{http_code} | %{content_type}
" -I "$P"; echo "=== feed count ==="; rg -o '"id"' /tmp/feed.json | wc -l

cd /tmp && B=https://ivx-holdings-platform.onrender.com; curl -s -m 30 -o feed.json -w "feed: HTTP %{http_code} | %{time_total}s
" "$B/api/ivx/video-platform/feed?limit=3"; V=$(rg -o '"video_url":"[^"]+"' feed.json | head -1 | sed 's/"video_url":"//;s/"$//'); P=$(rg -o '"poster_url":"[^"]+"' feed.json | head -1 | sed 's/"poster_url":"//;s/"$//'); T=$(rg -o '"thumbnail_url":"[^"]+"' feed.json | head -1 | sed 's/"thumbnail_url":"//;s/"$//'); echo "video:   ${V:0:100}"; echo "poster:  ${P:0:100}"; [ -n "$V" ] && curl -s -m 20 -o /dev/null -w "video asset:   HTTP %{http_code} | %{content_type} | %{size_download}B
" -I "$V"; [ -n "$P" ] && curl -s -m 20 -o /dev/null -w "poster asset:  HTTP %{http_code} | %{content_type}
" -I "$P"; [ -n "$T" ] && curl -s -m 20 -o /dev/null -w "thumb asset:   HTTP %{http_code} | %{content_type}
" -I "$T"; echo "feed videos: $(rg -o '"video_url"' feed.json | wc -l)"

cd /tmp && B=https://ivx-holdings-platform.onrender.com; curl -s -m 30 -o feed.json -w "feed: HTTP %{http_code} | %{time_total}s
" "$B/api/ivx/video-platform/feed?limit=3"; V=$(rg -o '"video_url":"[^"]+"' feed.json | head -1 | sed 's/"video_url":"//;s/"$//'); P=$(rg -o '"poster_url":"[^"]+"' feed.json | head -1 | sed 's/"poster_url":"//;s/"$//'); T=$(rg -o '"thumbnail_url":"[^"]+"' feed.json | head -1 | sed 's/"thumbnail_url":"//;s/"$//'); echo "videos in feed: $(rg -o '"video_url"' feed.json | wc -l)"; if [ -n "$V" ]; then curl -s -m 20 -o /dev/null -w "video asset:   HTTP %{http_code} | %{content_type}
" -I "$V"; fi; if [ -n "$P" ]; then curl -s -m 20 -o /dev/null -w "poster asset:  HTTP %{http_code} | %{content_type}
" -I "$P"; else echo "poster asset:  (null in feed)"; fi; if [ -n "$T" ]; then curl -s -m 20 -o /dev/null -w "thumb asset:   HTTP %{http_code} | %{content_type}
" -I "$T"; else echo "thumb asset:   (null in feed)"; fi; echo "first video url:"; echo "$V"
